import csv
import json
import sys
from datetime import datetime, timezone
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

STATUSES = {"SUCCESS", "FAILED", "PENDING"}

def parse_ts(raw):
    """Parse timestamp, handling ISO-8601, offsets, Z, naive (UTC), and epoch seconds."""
    raw = raw.strip()
    try:
        # Try parsing as float/int epoch seconds
        if raw.replace('.', '', 1).isdigit():
            dt = datetime.fromtimestamp(float(raw), tz=timezone.utc)
        else:
            # ISO format
            clean_raw = raw.replace("Z", "+00:00")
            dt = datetime.fromisoformat(clean_raw)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            else:
                dt = dt.astimezone(timezone.utc)
        return dt
    except Exception:
        raise ValueError("Invalid timestamp")

def parse_amount(raw):
    """Parse monetary amount, stripping currency symbols and commas."""
    cleaned = raw.strip().replace("$", "").replace(",", "")
    d = Decimal(cleaned)
    if not d.is_finite():
        raise InvalidOperation()
    return d

def load_rows(path):
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for idx, row in enumerate(reader):
            try:
                tx_id_raw = row.get("tx_id")
                ts_raw = row.get("timestamp")
                amt_raw = row.get("amount")
                status_raw = row.get("status")

                if not tx_id_raw or not ts_raw or not amt_raw or not status_raw:
                    continue

                tx_id = tx_id_raw.strip()
                if not tx_id:
                    continue

                ts = parse_ts(ts_raw)
                amount = parse_amount(amt_raw)
                status = status_raw.strip().upper()

                if status not in STATUSES:
                    continue

                rows.append({
                    "tx_id_norm": tx_id.lower(),
                    "ts": ts,
                    "amount": amount,
                    "status": status,
                    "index": idx
                })
            except (KeyError, AttributeError, ValueError, InvalidOperation):
                continue
    return rows

def dedupe(rows):
    """
    Rule 3:
    - Final (SUCCESS / FAILED) beats PENDING.
    - Among same kind, latest timestamp wins.
    - Tie: later row in file wins (higher index).
    """
    best = {}
    for r in rows:
        key = r["tx_id_norm"]
        is_final = 1 if r["status"] in ("SUCCESS", "FAILED") else 0

        if key not in best:
            best[key] = (is_final, r["ts"], r["index"], r)
        else:
            cur_final, cur_ts, cur_idx, cur_r = best[key]
            # Compare:
            # 1. is_final
            # 2. ts
            # 3. index
            candidate = (is_final, r["ts"], r["index"])
            current = (cur_final, cur_ts, cur_idx)
            if candidate > current:
                best[key] = (is_final, r["ts"], r["index"], r)
    return [item[3] for item in best.values()]

def summarize(rows):
    total = Decimal("0")
    valid_count = 0
    failed_count = 0

    for r in dedupe(rows):
        status = r["status"]
        if status == "FAILED":
            failed_count += 1
        elif status == "SUCCESS":
            valid_count += 1
            rounded_amount = r["amount"].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            total += rounded_amount
        # PENDING is ignored (neither valid nor failed)

    return {
        "total_valid_amount": float(total),
        "valid_count": valid_count,
        "failed_count": failed_count,
    }

def main():
    if len(sys.argv) != 2:
        print("usage: python3 reconcile.py <transactions.csv>", file=sys.stderr)
        sys.exit(2)
    try:
        rows = load_rows(sys.argv[1])
        result = summarize(rows)
        print(json.dumps(result))
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
